section.sourcecode:
struct codel_vars {
   u32             count;             /* ドロップされたパケットの数 */
   u32             lastcount;     /* ドロップ状態に入ったときのcount */
   bool            dropping;                /* 現在ドロップ中か？ */
   u16             rec_inv_sqrt;    /* 平方根の逆数の計算 */
   codel_time_t    first_above_time;    /* 遅延がtargetを超えた時刻 */
   codel_time_t    drop_next;                 /* 次にドロップする時刻 */
   codel_time_t    ldelay; /* 最後にデキューしたパケットの滞留時間 */
};

struct fq_codel_flow {
   struct sk_buff    *head;
   struct sk_buff    *tail;
   struct list_head  flowchain;
   int               credits;   /* キューの現在のクレジット数 */
   u32               dropped; /* フローでのドロップ（またはECNマーク）の数 */
   struct codel_vars cvars;
};

struct fq_codel_sched_data {
   struct tcf_proto *filter_list;  /* 任意の外部分類器 */
   struct fq_codel_flow *flows;    /* フローテーブル [flows_cnt] */
   u32             *backlogs;      /* バックログテーブル [flows_cnt] */
   u32             flows_cnt;      /* フローの数 */
   u32             perturbation;   /* ハッシュの摂動 */
   u32             quantum;        /* psched_mtu(qdisc_dev(sch)); */
   struct codel_params cparams;
   struct codel_stats cstats;
   u32             drop_overlimit;
   u32             new_flow_count;

   struct list_head new_flows;     /* 新しいフローのリスト */
   struct list_head old_flows;     /* 古いフローのリスト */
};
